    SELECT l.id INTO v_lesson_id FROM lessons l WHERE l.topic_id=v_topic_id AND l.title='Time Expressions and Context Clues';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons (topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES (v_topic_id,v_teacher_id,'Time Expressions and Context Clues','Connect words such as always, usually, today, and right now to tense choices.','Objective: Use common time expressions to select the correct present tense in everyday contexts.
Content: Frequency expressions often go with the present simple. Current-time expressions such as right now, this week, and today often go with the present continuous when the action is temporary or in progress.
Examples:
- She always checks her email.
- I am working from home this week.
- They are waiting right now.
Common errors and corrections:
- Place always before the main verb but after be.
- Do not choose a tense from one word alone; check whether the meaning is usual or temporary.
Guided practice: Circle the time expression and explain whether the situation is usual, factual, or temporary.
Summary: Time clues help, but meaning decides whether an action is a habit, fact, or current temporary event.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
