    IF v_lesson_id IS NULL THEN INSERT INTO lessons (topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES (v_topic_id,v_teacher_id,'State and Action Verbs','Practise know, like, want, need, understand, and remember in natural simple forms.','Objective: Avoid common A2 errors with verbs that normally describe states rather than temporary actions.
Content: Many state verbs describe thoughts, feelings, possession, or needs. At A2 they normally use the present simple, even when the state is true now.
Examples:
- I know the answer.
- She likes this song.
- We need more time.
Common errors and corrections:
- Prefer I know, not I am knowing.
- Use does with he, she, and it in negative questions: Does he want tea?
Guided practice: Decide whether each verb describes an action or a state before choosing the tense.
Summary: Use the present simple with common state verbs for current thoughts, feelings, wants, and needs.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
