    IF v_lesson_id IS NULL THEN INSERT INTO lessons (topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES (v_topic_id,v_teacher_id,'Integrated Everyday Choices','Combine form, time clues, and state/action distinctions in practical contexts.','Objective: Choose the correct present tense in short everyday conversations and messages.
Content: Read the whole situation before choosing. Ask whether the speaker describes a usual fact, a temporary arrangement, an action now, or a state.
Examples:
- I usually cycle, but I am taking the bus today.
- Do you know this address?
- We are meeting the teacher after class.
Common errors and corrections:
- Do not select continuous only because the sentence is about today.
- Check subject agreement: he works, but they work.
Guided practice: Explain the meaning first, then select the form that matches the context.
Summary: Accurate tense choice depends on both the time expression and the intended meaning.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
